package com.alpharip.staffmod.BuildTimelapse.ui;
import com.alpharip.staffmod.BuildTimelapse.capture.CaptureSettings;import net.minecraft.client.gui.GuiButton;import net.minecraft.client.gui.GuiScreen;
public final class CaptureSettingsScreen extends GuiScreen {
 private final GuiScreen parent;private final CaptureSettings settings;private String status="Changes apply to the next frame";
 public CaptureSettingsScreen(GuiScreen p,CaptureSettings s){if(p==null||s==null)throw new IllegalArgumentException();parent=p;settings=s;}
 @Override public boolean doesGuiPauseGame(){return false;}
 @Override public void initGui(){buttonList.clear();int x=width/2-100,y=height/2-60;buttonList.add(new GuiButton(0,x,y,200,20,"Interval: "+settings.getInterval()+" ms"));buttonList.add(new GuiButton(1,x,y+24,200,20,"HUD hidden: "+settings.isHideHud()));buttonList.add(new GuiButton(2,x,y+48,200,20,"Hand hidden: "+settings.isHideHand()));buttonList.add(new GuiButton(3,x,y+72,200,20,"Resolution: "+(settings.getWidth()==0?"Native":settings.getWidth()+"x"+settings.getHeight())));buttonList.add(new GuiButton(4,x,y+104,200,20,"Back"));}
 @Override protected void actionPerformed(GuiButton b){if(b.id==0){long[] v={250,500,1000,2000,5000,10000};int next=0;for(int i=0;i<v.length;i++)if(v[i]==settings.getInterval())next=(i+1)%v.length;settings.setInterval(v[next]);}else if(b.id==1)settings.setHideHud(!settings.isHideHud());else if(b.id==2)settings.setHideHand(!settings.isHideHand());else if(b.id==3){if(settings.getWidth()==0)settings.setResolution(1920,1080);else settings.setResolution(0,0);}else if(b.id==4){mc.displayGuiScreen(parent);return;}initGui();}
 @Override public void drawScreen(int mx,int my,float pt){drawDefaultBackground();drawCenteredString(fontRendererObj,"CAPTURE SETTINGS",width/2,28,0xFFC83D);drawCenteredString(fontRendererObj,status,width/2,height-24,0xBBBBBB);super.drawScreen(mx,my,pt);}
}